/* Concept mode uses the same model and a spacious, quiet presentation surface. */
.concept-intro,.concept-cutaway-control{display:none}
.concept-mode{background:#f1eee8}
.concept-mode main{max-width:1900px;padding-top:24px}
.concept-mode .intro{display:none}
.concept-mode .workspace{grid-template-columns:minmax(0,1fr) 330px;gap:20px}
.concept-mode .panel{border-color:#ded9d0;border-radius:12px}
.concept-mode .source-panel{background:#faf8f3;box-shadow:0 8px 32px #3b302a08}
.concept-mode .source-panel>.panel-heading{height:52px;background:#fffdf9;border-color:#e8e3da}
.concept-mode .source-panel .step{display:none}
.concept-mode .document-bar{padding:12px 20px 5px;color:#7c766b}
.concept-mode .view-tabs{padding:9px 20px 15px;border-color:#e5dfd5;gap:6px}
.concept-mode .view-tabs button{background:transparent;border-color:transparent;color:#777267;border-radius:6px;padding:9px 12px}
.concept-mode .view-tabs button:hover{background:#eae6dd}
