function syncViewerControls(snapshot) {
  if (!snapshot) return;
  $("floor-select").value = snapshot.floor_filter || "";
  $("explode-floors").checked = Boolean(snapshot.exploded);
  $("concept-cutaway").checked = snapshot.cutaway !== false;
  updateLayoutNote();
  renderFloorDetails();
}

function setView(view) {
  if (view === "concept" && !state.viewer) return;
  state.view = view;
  const concept = view === "concept";
  const model = view === "model" || concept;
  document.body.classList.toggle("concept-mode", concept);
  $("drawing-pane").hidden = view !== "drawing";
  $("model-pane").hidden = !model;
  $("show-model").setAttribute("aria-pressed", String(view === "model"));
  $("show-concept").setAttribute("aria-pressed", String(concept));
  $("show-drawing").setAttribute("aria-pressed", String(view === "drawing"));
  $("model-caption").textContent = concept
    ? "Drag to orbit · scroll to zoom · right-drag to pan"
    : "Drag to orbit · scroll to zoom · right-drag to pan · click an object to inspect its source.";
  if (model && state.viewer) {
    // Apply the new viewport size before the mode's initial camera framing.
    state.viewer.resize();
    syncViewerControls(state.viewer.setMode(concept ? "concept" : "inspection"));
    requestAnimationFrame(() => state.viewer?.resize());
  }
  renderInventory();
}

